CURLcode smtp_escape_eob(struct connectdata *conn, ssize_t nread) {
  ssize_t i, j;
  size_t crlf_count = 0;
  ssize_t new_size;
  char *scratch = NULL;
  CURLcode result = CURLE_OK;

  for (i = 0; i < nread - 1; ++i) {
    if (conn->upload_buffer[i] == '\r' && conn->upload_buffer[i + 1] == '\n') {
      ++crlf_count;
    }
  }

  if (crlf_count == 0) {
    return CURLE_OK;
  }

  new_size = nread + crlf_count;
  scratch = malloc(new_size);
  if (!scratch) {
    result = CURLE_OUT_OF_MEMORY;
    goto done;
  }

  for (i = 0, j = 0; i < nread; ++i) {
    if (i < nread - 1 && conn->upload_buffer[i] == '\r' && conn->upload_buffer[i + 1] == '\n') {
      scratch[j++] = '\r';
      scratch[j++] = '\n';
      scratch[j++] = '\r';
      scratch[j++] = '\n';
      ++i;
    } else {
      scratch[j++] = conn->upload_buffer[i];
    }
  }

  if (conn->upload_buffer != scratch) {
    free(conn->upload_buffer);
  }

  conn->upload_buffer = scratch;
  conn->upload_size += crlf_count;
  nread = new_size;

done:
  return result;
}

CURLcode escape_eob(struct connectdata *conn, ssize_t nread) {
  char *scratch = NULL;
  char *src, *dst;
  size_t i, replacements = 0;
  CURLcode result = CURLE_OK;

  // Allocate scratch buffer
  scratch = malloc(nread + 2); // Extra space for potential CRLF addition
  if (!scratch) {
    result = CURLE_OUT_OF_MEMORY;
    goto cleanup;
  }

  src = conn->upload_buffer;
  dst = scratch;

  for (i = 0; i < (size_t)nread; i++) {
    *dst++ = *src++;
    if (i + 1 < (size_t)nread && *src == '\r') {
      // Check for CRLF sequence
      if (i + 2 < (size_t)nread && *(src + 1) == '\n') {
        // Found CRLF, escape it by replacing with CRLF.CRLF
        *dst++ = *src++; // Copy '\r'
        *dst++ = '\r';
        *dst++ = '\n';
        replacements++;
        i++;
        continue;
      }
    }
  }

  if (replacements > 0) {
    // Free previous upload buffer
    free(conn->upload_buffer);
    conn->upload_buffer = scratch;
    conn->upload_size = dst - scratch;
    conn->current_upload_pos = 0;
  } else {
    // No replacements, return original buffer
    free(scratch);
  }

cleanup:
  if (scratch && !conn->upload_buffer) {
    free(scratch);
  }

  return result;
}

CURLcode escape_eob(struct connectdata *conn, ssize_t nread) {
  char *scratch = NULL;
  size_t i, j, replacements = 0;
  CURLcode result = CURLE_OK;

  scratch = malloc(nread + 2 * conn->smtp.crlf_count + 1);
  if (!scratch) {
    result = CURLE_OUT_OF_MEMORY;
    goto cleanup;
  }

  for (i = 0, j = 0; i < nread; ++i) {
    if (conn->upload_buffer[i] == '\r' && i + 1 < nread && conn->upload_buffer[i + 1] == '\n') {
      scratch[j++] = '.';
      replacements++;
    }

    scratch[j++] = conn->upload_buffer[i];
  }

  if (replacements > 0) {
    // Free any previous upload buffer
    if (conn->upload_buffer != conn->original_upload_buffer) {
      free(conn->upload_buffer);
    }

    conn->upload_buffer = scratch;
    scratch = NULL;
    conn->upload_size = j;
  }

cleanup:
  if (scratch) {
    free(scratch);
  }

  return result;
}

CURLcode escape_eob(struct connectdata *conn, ssize_t nread) {
  size_t i;
  ssize_t replacements = 0;
  unsigned char *scratch = NULL;
  unsigned char *src, *dst;
  CURLcode result = CURLE_OK;

  if (!conn || nread <= 0) {
    return CURLE_OK;
  }

  src = (unsigned char *)conn->upload->data;
  scratch = malloc(nread + 2); /* +2 for possible extra CRLF added */
  if (!scratch) {
    return CURLE_OUT_OF_MEMORY;
  }

  dst = scratch;
  for (i = 0; i < (size_t)nread; ++i) {
    if (src[i] == '\r' && i + 1 < (size_t)nread && src[i + 1] == '\n') {
      *dst++ = '\r';
      *dst++ = '\n';
      ++replacements;
      i++; /* skip the next '\n' */
    } else {
      *dst++ = src[i];
    }
  }

  *dst = '\0'; /* Null-terminate the buffer for safe operations if needed. */

  if (replacements > 0) {
    /* Free the old buffer */
    free(conn->upload->data);

    conn->upload->data = scratch;
    conn->upload->size = (size_t)(dst - scratch);
    conn->upload->left = conn->upload->size;
  } else {
    free(scratch);
  }

  return result;
}

CURLcode escape_eob_markers(struct connectdata *conn, ssize_t nread) {
    char *scratch = NULL;
    size_t scratch_len = 0;
    size_t i, j;
    size_t num_replacements = 0;
    CURLcode result = CURLE_OK;

    /* Allocate initial scratch buffer */
    scratch = malloc(nread + 2);
    if (!scratch) {
        result = CURLE_OUT_OF_MEMORY;
        goto cleanup;
    }

    for (i = 0, j = 0; i < nread; i++) {
        if (i + 1 < nread && conn->uploadbuf[i] == '\r' && conn->uploadbuf[i + 1] == '\n') {
            /* Replace CRLF with escaped EOB marker (CRLF . CRLF) */
            scratch[j++] = '.';
            num_replacements++;
            i++;  // Skip the next character (LF)
        } else {
            scratch[j++] = conn->uploadbuf[i];
        }
    }

    if (num_replacements > 0) {
        /* Update the upload buffer with the new data */
        free(conn->uploadbuf);
        conn->uploadbuf = scratch;
        scratch = NULL;
        conn->uploadbuf_size = nread + num_replacements * 2;
    }

cleanup:
    if (scratch) {
        free(scratch);
    }
    return result;
}
